INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (429805, 16593, 'South China Morning Post', 'en', 'China-Nepal floods: rescuers pull out survivors caked in mud as toll climbs', 'https://www.scmp.com/news/asia/south-asia/article/3365668/china-nepal-floods-rescuers-pull-out-survivors-caked-mud-toll-climbs', 'Rescuers pulled out survivors caked in dark brown mud and helicopters lifted stranded people to safety, as Nepal and China raced to respond to catastrophic flash floods that killed nearly 600 people and left almost 2,500 missing. The rescue efforts included a team that rappelled into a severely damaged checkpoint area on the Chinese side of the border between the two countries. Rescuers were on high alert for more flooding from a new lake that formed high up in the Himalayan mountains after the...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/29/e21c7c86-f292-4ab1-acf8-948760fdf82e_59c76ba1.jpg?itok=i810zXgK&v=1787951490', '2026-08-28T20:21:45+00:00', '2026-08-29T00:09:28.469722'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
