INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (425242, 16602, 'South China Morning Post', 'en', 'Storm travel chaos as Typhoon Saudel makes double landfall in China', 'https://www.scmp.com/news/china/article/3365546/storm-travel-chaos-typhoon-saudel-makes-double-landfall-china', 'Typhoon Saudel made landfall in the eastern Chinese province of Zhejiang on Friday morning, disrupting flights and ferry services across major urban centres, including the industrial hub of Ningbo and the economic powerhouse of Shanghai. Ningbo Lishe International Airport suspended all flight operations from 11.30pm on Thursday. Even though services resumed at 11am on Friday, some 16 inbound and 28 outbound flights were cancelled for the day. In the Zhejiang city of Wenzhou, a base for private...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/28/ad6d3851-4784-48a2-9038-4d5deac6c99e_2eda2ebb.jpg?itok=I_n7_orL&v=1787904967', '2026-08-28T05:15:41+00:00', '2026-08-28T12:53:51.894449'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
