INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (425240, 16603, 'South China Morning Post', 'en', 'Waves of attacks in Thailand’s deep south leave villagers trapped in a cycle of fear', 'https://www.scmp.com/news/asia/southeast-asia/article/3365551/waves-attacks-thailands-deep-south-leave-villagers-trapped-cycle-fear', 'Security guard Ni-arfan Doloh was taking a routine photograph for his nightly report on Saturday when five masked men carrying rifles emerged from inside a government office in Thailand’s southern Narathiwat province. “I was shocked,” said Ni-arfan, 25, recalling how they led him and another guard behind the Chang Phueak subdistrict office, instructed them to sit with their hands behind their backs, and promised no harm would come to them. The masked men then set fire to the building, one of at...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/28/1bbbe874-7f15-43ed-9927-05b97062fabb_42fa5c43.jpg?itok=jbyXfF1X&v=1787895878', '2026-08-28T05:44:41+00:00', '2026-08-28T12:53:51.875441'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
