INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422584, 16619, 'The Guardian', 'en', 'Healey’s budget to duck setting a date for 3% defence spending target', 'https://www.theguardian.com/business/2026/aug/28/john-healey-uk-defence-spending-target-budget', 'Roadmap for increasing department’s share of GDP will be deferred until next year’s review The chancellor will delay setting out when the UK will meet the target of allocating 3% of GDP on defence until next year’s spending review, the Treasury has confirmed. John Healey resigned as defence secretary in June under Keir Starmer’s leadership, accusing the prime minister of being “unable” and the Treasury “unwilling” to “commit the resources that the nation needs to defend the country”. Continue reading...', 'https://i.guim.co.uk/img/media/74be507303f27aac2281af5d24f3edcfb60b7be0/371_0_4410_3531/master/4410.jpg?width=140&quality=85&auto=format&fit=max&s=db6b05b451dd0e7dd1e4149230d2b067', '2026-08-28T10:00:22+00:00', '2026-08-28T12:49:05.819773'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
